"""Shared visual styling for the read-only logsim pages."""
THEME = """
:root{color-scheme:light;--ink:#202c3c;--muted:#748094;--line:#e5eaf1;--blue:#2463db;--surface:#fff}
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}
a{color:var(--blue);text-decoration:none}a:hover{color:#1746a5;text-decoration:underline}a:focus-visible,input:focus-visible{outline:3px solid #95bbff;outline-offset:3px}
.topbar{height:60px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 32px}
.brand{display:flex;align-items:center;gap:10px;font-size:18px;font-weight:750;letter-spacing:-.5px}.brand-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#2463db;color:#fff;font-size:17px}.top-note{color:var(--muted);font-size:12px}
main{max-width:1600px;margin:0 auto;padding:28px 32px 40px}.page-head{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:24px}h1{font-size:26px;letter-spacing:-.7px;margin:0 0 5px;font-weight:700}.page-head p{margin:0;color:var(--muted)}
.stats{display:flex;align-items:center;gap:26px}.stat{padding-left:24px;border-left:1px solid #dce3ef;white-space:nowrap}.stat strong{display:block;font-size:24px;line-height:1.3;font-variant-numeric:tabular-nums}.stat span{color:var(--muted);font-size:12px}
.toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;margin:0 0 22px;border-bottom:1px solid var(--line);padding-bottom:12px}nav{display:flex;gap:6px}nav a{padding:7px 14px;color:#536176;border-radius:7px;font-weight:600}nav a:hover{background:#eaf0fc;color:var(--blue);text-decoration:none}nav small{margin-left:6px;color:#8995a8}.search{width:280px;padding:9px 12px;border:1px solid #dce3ed;border-radius:8px;background:white;font:inherit}
section{scroll-margin-top:20px;margin-bottom:28px}.section-head{display:flex;align-items:baseline;gap:10px;margin-bottom:10px}.section-head h2{font-size:16px;font-weight:700;margin:0}.section-head p{font-size:12px;color:var(--muted);margin:0}.count{font-size:12px;color:#5e708b;background:#e9eef6;padding:1px 7px;border-radius:5px}
.table-scroll,.scroll{overflow-x:auto;border:1px solid var(--line);border-radius:10px;background:white;box-shadow:0 2px 5px #26364e03}table{border-collapse:collapse;width:100%;background:white;font-size:13px}th,td{padding:12px 16px;text-align:left;vertical-align:middle;border-bottom:1px solid #edf0f5}th{font-size:12px;letter-spacing:.2px;color:#738197;background:#fafbfd;font-weight:600;white-space:nowrap}tbody tr:last-child td{border-bottom:0}tbody tr:hover{background:#f8faff}.num{font-variant-numeric:tabular-nums;text-align:center}th.num{text-align:center}.muted{color:var(--muted);overflow-wrap:anywhere}small{font-size:11px}.scene-table{min-width:1100px}.scene-name{width:23%;overflow-wrap:anywhere;font-weight:600}.scene-name small{font-weight:400}.description{width:25%;color:#607086;line-height:1.65}.actions{min-width:155px;line-height:1.9;font-size:12px}.actions a:first-child{font-weight:600}.badge{display:inline-flex;align-items:center;gap:5px;border-radius:5px;background:#f1f4f8;padding:3px 8px;font-size:12px;font-weight:600;white-space:nowrap}.badge::before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}.badge.good{color:#188563;background:#eaf7f1}.badge.bad{color:#bd3946;background:#fff0f1}.badge.warn{color:#a37522;background:#fff6e6}.badge.neutral{color:#748094;background:#f0f3f7}.report-time{font-weight:600;font-variant-numeric:tabular-nums}.report-open{font-size:12px;white-space:nowrap}.empty{padding:22px;background:#fff;border:1px dashed #dce3ed;border-radius:8px;color:var(--muted)}footer{color:#8a95a7;font-size:12px;border-top:1px solid var(--line);padding-top:16px;margin-top:24px}.filter-empty{padding:12px;color:var(--muted)}
@media(max-width:850px){.topbar{padding:0 16px}main{padding:20px 16px}.page-head{align-items:flex-start}.stats{gap:12px}.stat{padding-left:12px}.stat strong{font-size:20px}.toolbar{align-items:stretch;flex-direction:column;gap:10px}.search{width:100%}.top-note{display:none}}@media(max-width:550px){.page-head{flex-direction:column;gap:16px}.stats{width:100%;justify-content:space-between}.stat:first-child{border:0;padding-left:0}nav a{padding:6px 8px}}
"""

